$sql$;
do $$
declare r uuid:=gen_random_uuid(); f jsonb:=pg_temp.ledger_fixture(); p jsonb; bad jsonb; o jsonb; t text;
begin
  insert into nohut_private.restaurants(restaurant_id) values(r);
  for o in select value from jsonb_array_elements(f->'orders') loop
    perform nohut_private.apply_typed_order(r,1,o->>'local_order_id',o);
  end loop;
  perform nohut_private.apply_typed_ledger(r,1,'combinedPayments',f->'combined');
  perform nohut_private.apply_typed_ledger(r,1,'terminalAttempts',f->'terminal');
  perform nohut_private.apply_typed_ledger(r,1,'cashBook',f->'cash');
  set constraints all immediate;set constraints all deferred;
  if (select count(*) from nohut_private.combined_payment_groups where restaurant_id=r)<>1
    or (select count(*) from nohut_private.combined_payment_members where restaurant_id=r)<>2
    or (select count(*) from nohut_private.terminal_attempt_events where restaurant_id=r)<>4
    or (select expected_kurus from nohut_private.cash_sessions where restaurant_id=r)<>11000
    or (select difference_kurus from nohut_private.cash_sessions where restaurant_id=r)<>0 then raise exception 'ledger facts missing';end if;
  p:=f->'combined';
  foreach bad in array array[
    jsonb_set(p,'{rows,0,data,amount_kurus}','3001'),
    jsonb_set(p,'{rows,0,data,received_kurus}','null'),
    jsonb_set(p,'{rows,0,data,received_kurus}','1600'),
    jsonb_set(p,'{rows,1,data,order_id}',to_jsonb(gen_random_uuid())),
    jsonb_set(p,'{rows,0,data,recorded_at}','"2026-11-27T12:00:00Z"'),
    jsonb_set(p,'{rows,0,data,customer_phone}','"synthetic"'),
    jsonb_set(p,'{counts,combined_payment_members}','1')
  ] loop
    begin perform nohut_private.apply_typed_ledger(r,2,'combinedPayments',bad);raise exception 'bad combined ledger accepted';exception when invalid_parameter_value then null;end;
  end loop;
  p:=f->'terminal';
  foreach bad in array array[
    jsonb_set(p,'{rows,0,data,amount_kurus}','1001'),
    jsonb_set(p,'{rows,0,data,status}','"unknown"'),
    jsonb_set(p,'{rows,0,data,transaction_id}','"another-transaction"'),
    jsonb_set(p,'{rows,0,data,order_id}',to_jsonb(gen_random_uuid())),
    jsonb_set(p,'{rows,1,data,status}','"declined"'),
    jsonb_set(p,'{rows,0,data,pan}','"never-allowed"'),
    jsonb_set(p,'{counts,terminal_attempt_events}','3')
  ] loop
    begin perform nohut_private.apply_typed_ledger(r,2,'terminalAttempts',bad);raise exception 'bad terminal ledger accepted';exception when invalid_parameter_value then null;end;
  end loop;
  p:=f->'cash';
  foreach bad in array array[
    jsonb_set(p,'{rows,0,data,difference_kurus}','1'),
    jsonb_set(p,'{rows,0,data,opening_kurus}','10001'),
    jsonb_set(p,'{rows,1,data,amount_kurus}','-201'),
    jsonb_set(p,'{rows,0,data,counted_kurus}','"11000"'),
    jsonb_set(jsonb_set(p,'{rows}',(p->'rows')-1),'{counts,cash_movements}','0')
  ] loop
    begin perform nohut_private.apply_typed_ledger(r,2,'cashBook',bad);raise exception 'bad cash ledger accepted';exception when invalid_parameter_value then null;end;
  end loop;
  if exists(select 1 from nohut_private.typed_record_history where restaurant_id=r)
    or (select count(*) from nohut_private.payments where restaurant_id=r)<>4 then raise exception 'invalid ledger partly persisted';end if;
  foreach t in array array['combined_payment_groups','combined_payment_members','terminal_attempts','terminal_attempt_events','cash_sessions','cash_movements'] loop
    if has_table_privilege('authenticated','nohut_private.'||t,'select,insert,update,delete') or has_table_privilege('anon','nohut_private.'||t,'select,insert,update,delete') then
      raise exception 'financial ledger grant leaked';end if;
  end loop;
end $$;
set local role authenticated;
do $$ begin
  begin perform 1 from nohut_private.terminal_attempts;raise exception 'client read terminals';exception when insufficient_privilege then null;end;
  begin perform 1 from nohut_private.cash_sessions;raise exception 'client read cash sessions';exception when insufficient_privilege then null;end;
end $$;
reset role;
rollback;
